// 1. Dynamically track the node's IPv6 address from incoming UDP packets
if (msg.payload && msg.payload.nodeId) {
    var nodeId = msg.payload.nodeId;
    var nodeIp = msg.ip;
    flow.set("node_ip_" + nodeId, nodeIp);
    node.log("Tracked node " + nodeId + " with IPv6: " + nodeIp);
}

// 2. Dispatch the event to the correct Akka HTTP endpoint
var event = msg.payload.event;
if (event === "parent_change") {
    msg.url = "http://localhost:8080/parentChanged";
    msg.method = "POST";
    msg.payload = {
        nodeId: msg.payload.nodeId.toString(),
        newParent: msg.payload.newParent,
        oldParent: msg.payload.oldParent || ""
    };
    return [msg, null, null];
} else if (event === "app_message") {
    msg.url = "http://localhost:8080/appMessage";
    msg.method = "POST";
    msg.payload = {
        nodeId: msg.payload.nodeId.toString(),
        seq: msg.payload.seq
    };
    return [null, msg, null];
} else if (event === "crash") {
    msg.url = "http://localhost:8080/crash";
    msg.method = "POST";
    msg.payload = {
        nodeId: msg.payload.nodeId.toString()
    };
    return [null, null, msg];
}

return null;

var nodeId = msg.payload.nodeId;
var newPeriod = msg.payload.newPeriod;

// 1. Retrieve the dynamically tracked IPv6 address for this node
// Fallback pattern to fd00::202, fd00::203, fd00::204 etc. if no packet has been tracked yet
var defaultIp = "fd00::20" + nodeId;
var targetIp = flow.get("node_ip_" + nodeId) || defaultIp;

// 2. Prepare payload exactly as expected by C firmware callback (newPeriod:T)
msg.ip = targetIp;
msg.port = 5010;
msg.payload = "newPeriod:" + newPeriod;

node.log("Routing command for node " + nodeId + " to " + targetIp + ":5010 - payload: " + msg.payload);

// 3. Keep a copy for HTTP response and routing to Akka
var akkaMsg = {
    url: "http://localhost:8080/setPeriod",
    method: "POST",
    payload: {
        nodeId: nodeId.toString(),
        newPeriod: parseInt(newPeriod)
    }
};

var httpResponse = {
    payload: {
        status: "success",
        nodeId: nodeId,
        targetIp: targetIp,
        newPeriod: newPeriod
    }
};

return [msg, akkaMsg, httpResponse];
